import {people,relationships,places} from './data.js';
import {MIN_YEAR,MAX_YEAR,clamp,cohort,eventAt,visiblePeople,relatives} from './model.js';
import {Globe} from './globe.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={year:1870,selected:'ines',branch:'all',view:'tree',kind:'birth',query:''};
const globe=new Globe($('globe'),id=>selectPerson(id));
const eras=['The first chapters','Across the ocean','New roots','A wider world','The next chapter'];
let treeKey='';
const mobile=matchMedia('(max-width:800px)');
function position(p){return mobile.matches?{x:10+(p.col%2)*186,y:25+p.row*170+Math.floor(p.col/2)*70}:{x:14+p.col*186,y:25+p.row*117};}
function renderTree(){const camera=mobile.matches?clamp((state.year-1880)/34*170-65,-20,470):clamp((state.year-1880)/34*117-95,-55,210);$('tree').setAttribute('viewBox',`0 ${camera} ${mobile.matches?380:760} 470`);const list=visiblePeople(people,state.branch),ids=new Set(list.map(p=>p.id));const match=p=>!state.query||p.name.toLowerCase().includes(state.query.toLowerCase());
 const key=state.branch+'|'+state.query;if(key!==treeKey||!$('tree').children.length){treeKey=key;const edges=relationships.filter(([a,b])=>ids.has(a)&&ids.has(b)).map(([a,b,type])=>{const pa=position(people.find(p=>p.id===a)),pb=position(people.find(p=>p.id===b));const d=type==='partner'?`M${pa.x+162},${pa.y+28} L${pb.x},${pb.y+28}`:`M${pa.x+81},${pa.y+58} C${pa.x+81},${pa.y+92} ${pb.x+81},${pb.y-33} ${pb.x+81},${pb.y}`;return`<path class="edge ${type}" data-a="${a}" data-b="${b}" d="${d}"/>`;}).join('');
 $('tree').innerHTML=edges+list.map(p=>{const {x,y}=position(p);return`<g class="node" role="button" tabindex="0" data-id="${p.id}" aria-label="${esc(p.name)}, born ${p.birth}" transform="translate(${x},${y})"><rect width="162" height="58" rx="7"/><circle class="avatar" cx="23" cy="28" r="14"/><text class="initial" x="23" y="33" text-anchor="middle">${p.name[0]}</text><text x="45" y="24">${esc(p.name)}</text><text class="years" x="45" y="42">${p.birth}${p.death?' — '+p.death:' · '+esc(p.branch)}</text></g>`;}).join('');
 $('tree').querySelectorAll('.node').forEach(node=>{node.addEventListener('click',()=>selectPerson(node.dataset.id));node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectPerson(node.dataset.id);}});});}
 $('tree').querySelectorAll('.node').forEach(node=>{const p=people.find(p=>p.id===node.dataset.id);node.classList.toggle('selected',p.id===state.selected);node.classList.toggle('context',!match(p)||(!cohort(p,state.year)&&p.id!==state.selected));node.setAttribute('aria-pressed',p.id===state.selected?'true':'false');});
 $('tree').querySelectorAll('.edge').forEach(edge=>{edge.classList.toggle('highlight',edge.dataset.a===state.selected||edge.dataset.b===state.selected);});
 $('empty-search').hidden=!state.query||list.some(match);
 $('count').textContent=`${list.length} people · ${list.filter(p=>cohort(p,state.year)).length} in this birth cohort`;
}
function renderPanel(){const p=people.find(p=>p.id===state.selected),rel=relatives(p.id,people,relationships);$('person-panel').innerHTML=`<div class="profile-top"><span>A THREAD IN THE ATLAS</span><span>↗</span></div><div class="portrait" aria-hidden="true">${p.name.split(' ').map(s=>s[0]).join('')}</div><h2>${esc(p.name)}</h2><div class="lifespan">${p.birth}${p.death?' — '+p.death:' · Death not recorded'}</div><p class="bio">${esc(p.bio)}</p><button class="jump" id="jump-birth">Travel to ${p.birth} ↓</button><div class="panel-heading">PLACES IN A LIFE</div>${p.events.map(e=>`<div class="event"><span>${e.year} · ${e.type==='birth'?'Born':'Residence recorded'}<em data-event-year="${e.year}">${e.year>state.year?' · After selected year':''}</em></span>${esc(places[e.place].name)}</div>`).join('')}<div class="panel-heading">CONNECTED PEOPLE</div>${rel.map(r=>`<button class="relative" data-relative="${r.person.id}"><span>${esc(r.person.name)}</span><small>${r.label} ↗</small></button>`).join('')}<p class="panel-note">Fictional demonstration record. Biography and places are illustrative. Editing, voice stories and uploads are planned.</p>`;
 $('jump-birth').onclick=()=>goYear(p.birth);$('person-panel').querySelectorAll('[data-relative]').forEach(b=>b.onclick=()=>selectPerson(b.dataset.relative));}
function selectPerson(id){state.selected=id;const p=people.find(p=>p.id===id);if(state.branch!=='all'&&p.branch!==state.branch){state.branch='all';$('branch').value='all';}renderPanel();renderTree();updateGlobe(true);}
function mapPoints(){return visiblePeople(people,state.branch).filter(p=>!state.query||p.name.toLowerCase().includes(state.query.toLowerCase())).flatMap(p=>{const e=eventAt(p,state.year,state.kind);return e&&places[e.place]?[{id:p.id,name:p.name,year:e.year,place:places[e.place]}]:[];});}
function updateGlobe(focus=false){const points=mapPoints();globe.update(points,state.selected);if(focus){const p=points.find(p=>p.id===state.selected);if(p)globe.focus(p.place);}const grouped=new Map();for(const p of points){if(!grouped.has(p.place.name))grouped.set(p.place.name,[]);grouped.get(p.place.name).push(p);}$('locations').innerHTML=points.length?[...grouped].map(([name,group])=>`<button data-place="${group.find(p=>p.id===state.selected)?.id||group[0].id}" class="${group.some(p=>p.id===state.selected)?'active':''}" title="${esc(group.map(p=>p.name+' ('+p.year+')').join(', '))}">${esc(name)} · ${group.length}</button>`).join(''):'<p class="map-note">No dated locations in this view yet. Move forward in time or change the filter.</p>';$('locations').querySelectorAll('button').forEach(b=>b.onclick=()=>selectPerson(b.dataset.place));}
function renderYear(){const i=clamp(Math.floor((state.year-1870)/32),0,4);$('year').textContent=state.year;$('year-range').value=state.year;document.querySelector('.ghost-year').textContent=state.year;$('era').textContent=eras[i];$('chapter').textContent=`0${i+1} / 05`;$('progress').style.width=`${100*(state.year-MIN_YEAR)/(MAX_YEAR-MIN_YEAR)}%`;$('previous').disabled=state.year===MIN_YEAR;$('next').disabled=state.year===MAX_YEAR;renderTree();if(state.view==='earth')updateGlobe();$('person-panel').querySelectorAll('[data-event-year]').forEach(el=>{el.textContent=Number(el.dataset.eventYear)>state.year?' · After selected year':'';});}
function maxScroll(){return Math.max(1,document.documentElement.scrollHeight-innerHeight);}
function goYear(year){state.year=clamp(Math.round(year),MIN_YEAR,MAX_YEAR);window.scrollTo({top:(state.year-MIN_YEAR)/(MAX_YEAR-MIN_YEAR)*maxScroll(),behavior:'instant'});renderYear();}
let queued=false;window.addEventListener('scroll',()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;const fraction=clamp(scrollY/maxScroll(),0,1),year=Math.round(MIN_YEAR+fraction*(MAX_YEAR-MIN_YEAR));document.documentElement.style.setProperty('--parallax',`${(fraction-.5)*40}px`);if(year!==state.year){state.year=year;renderYear();}});},{passive:true});
function setView(view){state.view=view;$('tree-view').hidden=view!=='tree';$('earth-view').hidden=view!=='earth';$('tree-mode').setAttribute('aria-pressed',view==='tree');$('earth-mode').setAttribute('aria-pressed',view==='earth');$('view-description').textContent=view==='tree'?'Follow the threads. Discover the people between the years.':'One family. Many places. Explore the records across the Earth.';if(view==='earth')updateGlobe(true);}
$('tree-mode').onclick=()=>setView('tree');$('earth-mode').onclick=()=>setView('earth');$('year-range').oninput=e=>goYear(Number(e.target.value));$('previous').onclick=()=>goYear(state.year-10);$('next').onclick=()=>goYear(state.year+10);$('branch').onchange=e=>{state.branch=e.target.value;renderTree();updateGlobe();};$('event-kind').onchange=e=>{state.kind=e.target.value;updateGlobe(true);};$('zoom-in').onclick=()=>globe.resizeZoom(.15);$('zoom-out').onclick=()=>globe.resizeZoom(-.15);$('rotate-left').onclick=()=>globe.rotate(-25);$('rotate-right').onclick=()=>globe.rotate(25);
$('search').oninput=e=>{state.query=e.target.value.trim();const matches=visiblePeople(people,state.branch).filter(p=>p.name.toLowerCase().includes(state.query.toLowerCase()));$('search-results').hidden=!state.query;$('search-results').innerHTML=matches.length?matches.map(p=>`<button data-result="${p.id}">${esc(p.name)} · ${p.birth}</button>`).join(''):'No matching people';$('search-results').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectPerson(b.dataset.result);$('search-results').hidden=true;goYear(people.find(p=>p.id===b.dataset.result).birth);});renderTree();updateGlobe();};$('search').onkeydown=e=>{if(e.key==='Escape'){$('search-results').hidden=true;e.target.blur();}};document.addEventListener('click',e=>{if(!e.target.closest('.filters'))$('search-results').hidden=true;});
mobile.addEventListener('change',()=>{treeKey='';renderTree();});
renderPanel();renderYear();
